namespace ks{namespace{PanelTextPartialTest partialTest=nullptr;using T=PanelTextTask;using S=T::Stage;using K=T::Kind;struct Point{unsigned location,length;};Point point(const T&t){switch(t.stage()){case S::TestInput:return{0x976,2};case S::AdmitSign:return{0x978,2};case S::DispatchWrite:return{0x97a,4};case S::CompareBoth:return{0x980,2};case S::AdmitBoth:return{0x982,2};case S::DispatchSecondBoth:return{0x984,2};case S::DispatchFirstBoth:return{0x986,2};case S::CompareFirst:return{0x98a,2};case S::AdmitFirst:return{0x98c,2};case S::DispatchFirstOnly:return{0x98e,2};case S::CompareSecond:return{0x992,2};case S::AdmitSecond:return{0x994,2};case S::DispatchSecondOnly:return{0x996,2};case S::CompareCursor:return{0x99a,2};case S::AdmitCursor:return{0x99c,2};case S::SetCursor:return{0x99e,2};case S::DispatchCursor:return{0x9a0,4};case S::CompareDisplay:return{0x9a6,2};case S::AdmitDisplay:return{0x9a8,2};case S::SetDisplay:return{0x9aa,2};case S::DispatchDisplay:return{0x9ac,4};case S::DispatchCommand:return{0x9b2,4};case S::AwaitDispatchWrite:return{0x97e,2};case S::AwaitDispatchSecondBoth:return{0x986,2};case S::AwaitDispatchFirstBoth:return{0x988,2};case S::AwaitDispatchFirstOnly:return{0x990,2};case S::AwaitDispatchSecondOnly:return{0x998,2};case S::AwaitDispatchCursor:return{0x9a4,2};case S::AwaitDispatchDisplay:return{0x9b0,2};case S::AwaitDispatchCommand:return{0x9b6,2};case S::HoldText:return{t.kind()==K::Parsed?0x9b8u:0x9ccu,t.kind()==K::Parsed?4u:2u};case S::BindText:return{0x9bc,2};case S::ReadText:return{t.kind()==K::Parsed?0x9beu:0x9ceu,2};case S::AdmitText:return{t.kind()==K::Parsed?0x9c0u:0x9d0u,2};case S::DispatchText:return{t.kind()==K::Parsed?0x9c2u:0x9d2u,t.kind()==K::Parsed?2u:4u};case S::AwaitDispatchText:case S::RepeatText:return{t.kind()==K::Parsed?0x9c4u:0x9d6u,2};case S::RestoreText:return{t.kind()==K::Parsed?0x9c6u:0x9d8u,t.kind()==K::Parsed?4u:2u};case S::Finish:if(t.kind()!=K::Parse)return{t.kind()==K::Parsed?0x9cau:0x9dau,2};switch(t.action()){case T::Action::Write:return{0x97e,2};case T::Action::ClearBoth:return{0x988,2};case T::Action::ClearFirst:return{0x990,2};case T::Action::ClearSecond:return{0x998,2};case T::Action::Cursor:return{0x9a4,2};case T::Action::Display:return{0x9b0,2};case T::Action::Command:return{0x9b6,2};}break; default:break;}throw std::runtime_error("Invalid panel text stage");}}
bool PanelTextCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token-c->depth==h.getSP()){selected=&c;break;}if(pc==0x976||pc==0x9b8||pc==0x9cc){if(selected)throw std::runtime_error("Overlapping panel text");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Panel text capacity");selected->emplace(pc==0x976?K::Parse:pc==0x9b8?K::Parsed:K::Plain,h.getSP());++started;}if(!selected||point((**selected).task).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;auto&v=h.regs;if(t.child()!=T::Child::None)t.resumeChild();auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(t).length);auto source=[&]{return t.bound()?t.pointer():uint32_t(v[1].er);};auto clock=[&]{return (source()&0xffffff)>=0xfffd10?1u:3u;};auto cost=t.nextClocks(clock);t.advanceBefore(cost,[&](T::Read r)->uint32_t{return r==T::Read::Input?uint8_t(v[6].rl):r==T::Read::Pointer?uint32_t(t.kind()==K::Parsed?v[6].er:v[1].er):uint8_t(h.read8(t.pointer()&0xffffff));},clock);switch(stage){case S::TestInput:f.move(v[6].rl,v[6].rl);break;case S::CompareBoth:h.sub8(v[6].rl,0xffffffff);break;case S::CompareFirst:h.sub8(v[6].rl,0xfffffffe);break;case S::CompareSecond:h.sub8(v[6].rl,0xfffffffd);break;case S::CompareCursor:h.sub8(v[6].rl,0xfffffffc);break;case S::CompareDisplay:h.sub8(v[6].rl,0xfffffffb);break;case S::SetCursor:f.move(v[6].rl,14);break;case S::SetDisplay:f.move(v[6].rl,12);break;case S::HoldText:if(t.kind()==K::Parsed){f.push(v[5].er);(**selected).depth+=4;}else{f.push(v[6].r);(**selected).depth+=2;}break;case S::BindText:f.move(v[5].er,v[6].er);break;case S::ReadText:f.move(v[6].rl,int8_t(t.byte()));if(t.kind()==K::Parsed)v[5].er=int32_t(uint32_t(v[5].er)+1);else v[1].er=int32_t(uint32_t(v[1].er)+1);h.clockI(2);break;case S::RestoreText:if(t.kind()==K::Parsed){f.pop(v[5].er);(**selected).depth-=4;}else{f.pop(v[6].r);(**selected).depth-=2;}break;case S::DispatchWrite:f.call(0x90e);h.pc=h.makepc(f.next);break;case S::DispatchSecondBoth:f.call(0x952);h.pc=h.makepc(f.next);break;case S::DispatchFirstBoth:f.call(0x944);h.pc=h.makepc(f.next);break;case S::DispatchFirstOnly:f.call(0x944);h.pc=h.makepc(f.next);break;case S::DispatchSecondOnly:f.call(0x952);h.pc=h.makepc(f.next);break;case S::DispatchCursor:f.call(0x8fc);h.pc=h.makepc(f.next);break;case S::DispatchDisplay:f.call(0x8fc);h.pc=h.makepc(f.next);break;case S::DispatchCommand:f.call(0x8fc);h.pc=h.makepc(f.next);break;case S::DispatchText:f.call(t.kind()==K::Parsed?0x976:0x90e);h.pc=h.makepc(f.next);break; case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage!=S::Finish&&t.child()==T::Child::None)h.pc=h.makepc(point(t).location);if(h.cycles-before!=cost)throw std::runtime_error("Panel text clocks differ");return true;}}

